const body = $input.first()?.json?.body ?? $input.first()?.json ?? {};
const action = (body.action || 'open_url').toLowerCase();
const allowed = ['open_url','screenshot','close_browser'];
if (!allowed.includes(action)) {
  throw new Error('Invalid action. Must be one of: ' + allowed.join(', '));
}
const url = body.url || '';
const confirmed = body.confirmed === true || body.confirmed === 'true';
if (action === 'open_url' && !url) throw new Error('url is required for open_url action');
const urlPattern = /^https?:\/\//i;
if (url && !urlPattern.test(url)) throw new Error('URL must begin with http:// or https://');
return [{ json: { action, url, confirmed } }];

const raw = $input.first()?.json?.stdout ?? '';
let validation;
try { validation = JSON.parse(raw); } catch { validation = { allowed: true }; }
if (validation.allowed === false) {
  throw new Error('Safety validation blocked browser operation: ' + (validation.reason || 'policy'));
}
const params = $('Parse & Validate').first().json;
return [{ json: params }];

const raw = $input.first()?.json?.stdout ?? $input.first()?.json?.stderr ?? '';
let result;
try { result = JSON.parse(raw); } catch { result = { success: false, error: raw || 'No output from browser action' }; }
return [{ json: result }];
